static void *sqlite3Malloc(u64 n){
  void *p;
  if( n==0 || n>2147483391 ){
    p = 0;
  }else if( sqlite3Config.bMemstat ){
    sqlite3_mutex_enter(mem0.mutex);
    mallocWithAlarm((int)n, &p);
    sqlite3_mutex_leave(mem0.mutex);
  }else{
    p = sqlite3Config.m.xMalloc((int)n);
  }
  ;  /* IMP: R-11148-40995 */
  return p;
}

