  rc = walLockExclusive(pWal, iLock, (3+(0))-iLock);
  if( rc ){
    return rc;
  }

  ;

  memset(&pWal->hdr, 0, sizeof(WalIndexHdr));

  rc = sqlite3OsFileSize(pWal->pWalFd, &nSize);
  if( rc!=0    ){
    goto recovery_error;
  }

