/*
** Return the column declaration type (if applicable) of the 'i'th column
** of the result set of SQL statement pStmt.
*/
 const char *sqlite3_column_decltype(sqlite3_stmt *pStmt, int N){
  return columnName(pStmt, N, 0, 1);
}

 const void *sqlite3_column_decltype16(sqlite3_stmt *pStmt, int N){
  return columnName(pStmt, N, 1, 1);
}




































/******************************* sqlite3_bind_  ***************************
**
** Routines used to attach values to wildcards in a compiled SQL statement.
*/
/*
** Unbind the value bound to variable i in virtual machine p. This is the
** the same as binding a NULL value to the column. If the "i" parameter is
** out of range, then SQLITE_RANGE is returned. Otherwise SQLITE_OK.
**
** A successful evaluation of this routine acquires the mutex on p.
** the mutex is released if any kind of error occurs.
**
** The error code stored in database p->db is overwritten with the return
** value in any case.
**
** (tag-20240917-01) If  vdbeUnbind(p,(u32)(i-1))  returns SQLITE_OK,
** that means all of the the following will be true:
**
**     p!=0
**     p->pVar!=0
**     i>0
**     i<=p->nVar
**
** An assert() is normally added after vdbeUnbind() to help static analyzers
** realize this.
*/
static int vdbeUnbind(Vdbe *p, unsigned int i){
  Mem *pVar;
  if( vdbeSafetyNotNull(p) ){
    return sqlite3MisuseError(95187);
  }
  sqlite3_mutex_enter(p->db->mutex);
  if( p->eVdbeState!=1    ){
    sqlite3Error(p->db, sqlite3MisuseError(95191));
    sqlite3_mutex_leave(p->db->mutex);
    sqlite3_log(21   ,
        "bind on a busy prepared statement: [%s]", p->zSql);
    return sqlite3MisuseError(95195);
  }
  if( i>=(unsigned int)p->nVar ){
    sqlite3Error(p->db, 25   );
    sqlite3_mutex_leave(p->db->mutex);
    return 25   ;
  }
  pVar = &p->aVar[i];
  sqlite3VdbeMemRelease(pVar);
  pVar->flags = 0x0001   ;
  p->db->errCode = 0   ;

  /* If the bit corresponding to this variable in Vdbe.expmask is set, then
  ** binding a new value to this variable invalidates the current query plan.
  **
  ** IMPLEMENTATION-OF: R-57496-20354 If the specific value bound to a host
  ** parameter in the WHERE clause might influence the choice of query plan
  ** for a statement, then the statement will be automatically recompiled,
  ** as if there had been a schema change, on the first sqlite3_step() call
  ** following any change to the bindings of that parameter.
  */
  ;
  if( p->expmask!=0 && (p->expmask & (i>=31 ? 0x80000000 : (u32)1<<i))!=0 ){
    p->expired = 1;
  }
  return 0   ;
}

/*
** Bind a text or BLOB value.
*/
static int bindText(
  sqlite3_stmt *pStmt,   /* The statement to bind against */
  int i,                 /* Index of the parameter to bind */
  const void *zData,     /* Pointer to the data to be bound */
  i64 nData,             /* Number of bytes of data to be bound */
  void (*xDel)(void*),   /* Destructor for the data */
  u8 encoding            /* Encoding for the data */
){
  Vdbe *p = (Vdbe *)pStmt;
  Mem *pVar;
  int rc;

  rc = vdbeUnbind(p, (u32)(i-1));
  if( rc==0    ){
    ; /* tag-20240917-01 */
    if( zData!=0 ){
      pVar = &p->aVar[i-1];
      if( encoding==1     ){
        rc = sqlite3VdbeMemSetText(pVar, zData, nData, xDel);
      }else if( encoding==16     ){
        /* It is usually consider improper to assert() on an input.
        ** However, the following assert() is checking for inputs
        ** that are documented to result in undefined behavior. */
        ;
        rc = sqlite3VdbeMemSetText(pVar, zData, nData, xDel);
        pVar->flags |= 0x0200   ;
      }else{
        rc = sqlite3VdbeMemSetStr(pVar, zData, nData, encoding, xDel);
        if( encoding==0 ) pVar->enc = ((p->db)->enc);
      }
      if( rc==0    && encoding!=0 ){
        rc = sqlite3VdbeChangeEncoding(pVar, ((p->db)->enc));
      }
      if( rc ){
        sqlite3Error(p->db, rc);
        rc = sqlite3ApiExit(p->db, rc);
      }
    }
    sqlite3_mutex_leave(p->db->mutex);
  }else if( xDel!=((sqlite3_destructor_type)0) && xDel!=((sqlite3_destructor_type)-1) ){
    xDel((void*)zData);
  }
  return rc;
}


