  VdbeOp *pCaller;
  pIn1 = &aMem[pOp->p1];
  ;
  ;
  pCaller = &aOp[pIn1->u.i];
  ;
  ;
  pIn1->u.i = (int)(pOp - p->aOp) - 1;
  pOp = &aOp[pCaller->p2 - 1];
  break;
