  pIn1 = &aMem[pOp->p1];
  ;
  pIn1->flags = 0x0004   ;
  pcDest = (int)pIn1->u.i;
  pIn1->u.i = (int)(pOp - aOp);
  ;
  pOp = &aOp[pcDest];
