    sqlite3VdbeAddOp2(v, 129 , 0, reg1);
    sqlite3VdbeAddOp4(v, 79 , 6, reg3, 0, nullRow, (-1)  );
    sqlite3VdbeAddOp3(v, 130 , 0, reg3, reg1);
