      ;
      ;
      if( pTerm->wtFlags & (0x0002 |0x0004 ) ) continue;
      if( (pTerm->prereqAll & pLevel->notReady)!=0 ){
        ;
        continue;
      }
      if( pTabItem->fg.jointype & 0x40     ) continue;
