    ;
    sqlite3VdbeAddOp4Int(v, 29 , pRJ->iMatch, addrCont, r, nPk);
    ;
    sqlite3VdbeJumpHere(v, jmp);
    sqlite3VdbeAddOp2(v, 10 , pRJ->regReturn, pRJ->addrSubrtn);
