  sqlite3VdbeAddOp2(v, 129 , csrWrite, s.regRowid);
  sqlite3VdbeAddOp3(v, 130 , csrWrite, regRecord, s.regRowid);
  addrNe = sqlite3VdbeAddOp3(v, 53 , pMWin->regOne, 0, s.regRowid);
  ;

