    int addrStart;
    windowCodeOp(&s, 3, 0, 0);
    addrStart = sqlite3VdbeCurrentAddr(v);
    addrBreak = windowCodeOp(&s, 1, 0, 1);
    windowCodeOp(&s, 2, regStart, 0);
    sqlite3VdbeAddOp2(v, 9 , 0, addrStart);
    sqlite3VdbeJumpHere(v, addrBreak);
