/*
** Pop the parser's stack once.
**
** If there is a destructor routine associated with the token which
** is popped from the stack, then call it.
*/
static void yy_pop_parser_stack(yyParser *pParser){
  yyStackEntry *yytos;
  ;
  ;
  yytos = pParser->yytos--;







  yy_destructor(pParser, yytos->major, &yytos->minor);
}

/*
** Clear all secondary memory allocations from the parser
*/
static void sqlite3ParserFinalize(void *p){
  yyParser *pParser = (yyParser*)p;

  /* In-lined version of calling yy_pop_parser_stack() for each
  ** element left in the stack */
  yyStackEntry *yytos = pParser->yytos;
  while( yytos>pParser->yystack ){







    if( yytos->major>=206 ){
      yy_destructor(pParser, yytos->major, &yytos->minor);
    }
    yytos--;
  }


  if( pParser->yystack!=pParser->yystk0 ){
    parserStackFree(pParser->yystack, ((pParser)->pParse));
  }

}















/*
** Return the peak depth of the stack for a parser.
*/







/* This array of booleans keeps track of the parser statement
** coverage.  The element yycoverage[X][Y] is set when the parser
** is in state X and has a lookahead token Y.  In a well-tested
** systems, every element of this matrix should end up being set.
*/




/*
** Write into out a description of every state/lookahead combination that
**
**   (1)  has not been used by the parser, and
**   (2)  is not a syntax error.
**
** Return the number of missed state/lookahead combinations.
*/




















/*
** Find the appropriate action for a parser given the terminal
** look-ahead token iLookAhead.
*/
static unsigned short int yy_find_shift_action(
  unsigned short int iLookAhead,    /* The look-ahead token */
  unsigned short int stateno      /* Current state number */
){
  int i;

  if( stateno>599 ) return stateno;
  ;



  do{
    i = yy_shift_ofst[stateno];
    ;
    ;
    ;
    ;
    ;
    i += iLookAhead;
    ;
    if( yy_lookahead[i]!=iLookAhead ){

      unsigned short int iFallback;            /* Fallback token */
      ;
      iFallback = yyFallback[iLookAhead];
      if( iFallback!=0 ){






        ; /* Fallback loop must terminate */
        iLookAhead = iFallback;
        continue;
      }


      {
        int j = i - iLookAhead + 102;
        ;
        if( yy_lookahead[j]==102 && iLookAhead>0 ){







          return yy_action[j];
        }
      }

      return yy_default[stateno];
    }else{
      ;
      return yy_action[i];
    }
  }while(1);
}

/*
** Find the appropriate action for a parser given the non-terminal
** look-ahead token iLookAhead.
*/
static unsigned short int yy_find_reduce_action(
  unsigned short int stateno,     /* Current state number */
  unsigned short int iLookAhead     /* The look-ahead token */
){
  int i;





  ;

  i = yy_reduce_ofst[stateno];
  ;
  i += iLookAhead;





  ;
  ;

  return yy_action[i];
}

/*
** The following routine is called if the stack overflows.
*/
static void yyStackOverflow(yyParser *yypParser){
   
   Parse *pParse=yypParser->pParse;





   while( yypParser->yytos>yypParser->yystack ) yy_pop_parser_stack(yypParser);
   /* Here code is inserted which will execute if the parser
   ** stack every overflows */
/******** Begin %stack_overflow code ******************************************/

  if( pParse->nErr==0 ) sqlite3ErrorMsg(pParse, "Recursion limit");
/******** End %stack_overflow code ********************************************/
    /* Suppress warning about unused %extra_argument var */
   yypParser->pParse=pParse;
}

/*
** Print tracing information for a SHIFT action
*/


















/*
** Perform a shift action.
*/
static void yy_shift(
  yyParser *yypParser,          /* The parser to be shifted */
  unsigned short int yyNewState,      /* The new state to shift in */
  unsigned short int yyMajor,           /* The major token to shift in */
  Token yyMinor        /* The minor token to shift in */
){
  yyStackEntry *yytos;
  yypParser->yytos++;






  yytos = yypParser->yytos;
  if( yytos>yypParser->yystackEnd ){
    if( yyGrowStack(yypParser) ){
      yypParser->yytos--;
      yyStackOverflow(yypParser);
      return;
    }
    yytos = yypParser->yytos;
    ;
  }
  if( yyNewState > 599 ){
    yyNewState += 1282 - 867;
  }
  yytos->stateno = yyNewState;
  yytos->major = yyMajor;
  yytos->minor.yy0 = yyMinor;
  ;
}

