/* The main parser program.
** The first argument is a pointer to a structure obtained from
** "sqlite3ParserAlloc" which describes the current state of the parser.
** The second argument is the major token number.  The third is
** the minor token.  The fourth optional argument is whatever the
** user wants (and specified in the grammar) and is available for
** use by the action routines.
**
** Inputs:
** <ul>
** <li> A pointer to the parser (an opaque structure.)
** <li> The major token number.
** <li> The minor token number.
** <li> An option argument of a grammar-specified type.
** </ul>
**
** Outputs:
** None.
*/
static void sqlite3Parser(
  void *yyp,                   /* The parser */
  int yymajor,                 /* The major token code number */
  Token yyminor       /* The value for the token */
                 /* Optional %extra_argument parameter */
){
  YYMINORTYPE yyminorunion;
  unsigned short int yyact;   /* The parser action. */






  yyParser *yypParser = (yyParser*)yyp;  /* The parser */
  Parse *pParse=yypParser->pParse;
  

  ;




  yyact = yypParser->yytos->stateno;












  while(1){ /* Exit by "break" */
    ;
    ;
    yyact = yy_find_shift_action((unsigned short int)yymajor,yyact);
    if( yyact >= 1282 ){
      unsigned int yyruleno = yyact - 1282; /* Reduce by this rule */


















      /* Check that the stack is large enough to grow by a single entry
      ** if the RHS of the rule is empty.  This ensures that there is room
      ** enough on the stack to push the LHS value */
      if( yyRuleInfoNRhs[yyruleno]==0 ){







        if( yypParser->yytos>=yypParser->yystackEnd ){
          if( yyGrowStack(yypParser) ){
            yyStackOverflow(yypParser);
            break;
          }
        }
      }
      yyact = yy_reduce(yypParser,yyruleno,yymajor,yyminor ,pParse);
    }else if( yyact <= 1278 ){
      yy_shift(yypParser,yyact,(unsigned short int)yymajor,yyminor);



      break;
    }else if( yyact==1280 ){
      yypParser->yytos--;
      yy_accept(yypParser);
      return;
    }else{
      ;
      yyminorunion.yy0 = yyminor;














































      /* If the YYNOERRORRECOVERY macro is defined, then do not attempt to
      ** do any kind of error recovery.  Instead, simply invoke the syntax
      ** error routine and continue going as if nothing had happened.
      **
      ** Applications can set this macro (for example inside %include) if
      ** they intend to abandon the parse upon the first syntax error seen.
      */
      yy_syntax_error(yypParser,yymajor, yyminor);
      yy_destructor(yypParser,(unsigned short int)yymajor,&yyminorunion);
      break;















    }
  }












  return;
}

