    ; /* TEMP */
    ; /* OR */
    ; /* ISNULL */
    ; /* NULLS */
    ; /* SAVEPOINT */
    ; /* INTERSECT */
    ; /* TIES */
    ; /* NOTNULL */
    ; /* NOT */
    ; /* NO */
    ; /* NULL */
    ; /* LIKE */
    ; /* EXCEPT */
    ; /* TRANSACTION */
    ; /* ACTION */
    ; /* ON */
    ; /* NATURAL */
    ; /* ALTER */
    ; /* RAISE */
    ; /* EXCLUSIVE */
    ; /* EXISTS */
    ; /* CONSTRAINT */
    ; /* INTO */
    ; /* OFFSET */
