/*
** If X is a character that can be used in an identifier then
** IdChar(X) will be true.  Otherwise it is false.
**
** For ASCII, any character with the high-order bit set is
** allowed in an identifier.  For 7-bit characters,
** sqlite3IsIdChar[X] must be 1.
**
** For EBCDIC, the rules are more complex but have the same
** end result.
**
** Ticket #1066.  the SQL standard does not allow '$' in the
** middle of identifiers.  But many SQL implementations do.
** SQLite will allow '$' in identifiers for compatibility.
** But the feature is undocumented.
*/






















/* Make the IdChar function accessible from ctime.c and alter.c */
static int sqlite3IsIdChar(u8 c){ return ((sqlite3CtypeMap[(unsigned char)c]&0x46)!=0); }


/*
** Return the id of the next token in string (*pz). Before returning, set
** (*pz) to point to the byte following the parsed token.
*/
static int getToken(const unsigned char **pz){
  const unsigned char *z = *pz;
  int t;                          /* Token type to return */
  do {
    z += sqlite3GetToken(z, &t);
  }while( t==184 || t==185 );
  if( t==60
   || t==118
   || t==119
   || t==165
   || t==166
   || sqlite3ParserFallback(t)==60
  ){
    t = 60;
  }
  *pz = z;
  return t;
}

/*
** The following three functions are called immediately after the tokenizer
** reads the keywords WINDOW, OVER and FILTER, respectively, to determine
** whether the token should be treated as a keyword or an SQL identifier.
** This cannot be handled by the usual lemon %fallback method, due to
** the ambiguity in some constructions. e.g.
**
**   SELECT sum(x) OVER ...
**
** In the above, "OVER" might be a keyword, or it might be an alias for the
** sum(x) expression. If a "%fallback ID OVER" directive were added to
** grammar, then SQLite would always treat "OVER" as an alias, making it
** impossible to call a window-function without a FILTER clause.
**
** WINDOW is treated as a keyword if:
**
**   * the following token is an identifier, or a keyword that can fallback
**     to being an identifier, and
**   * the token after than one is TK_AS.
**
** OVER is a keyword if:
**
**   * the previous token was TK_RP, and
**   * the next token is either TK_LP or an identifier.
**
** FILTER is a keyword if:
**
**   * the previous token was TK_RP, and
**   * the next token is TK_LP.
*/
static int analyzeWindowKeyword(const unsigned char *z){
  int t;
  t = getToken(&z);
  if( t!=60 ) return 60;
  t = getToken(&z);
  if( t!=24 ) return 60;
  return 165;
}
static int analyzeOverKeyword(const unsigned char *z, int lastToken){
  if( lastToken==23 ){
    int t = getToken(&z);
    if( t==22 || t==60 ) return 166;
  }
  return 60;
}
static int analyzeFilterKeyword(const unsigned char *z, int lastToken){
  if( lastToken==23 && getToken(&z)==22 ){
    return 167;
  }
  return 60;
}


/*
** Return the length (in bytes) of the token that begins at z[0].
** Store the token type in *tokenType before returning.
*/
static i64 sqlite3GetToken(const unsigned char *z, int *tokenType){
  i64 i;
  int c;
  switch( aiClass[*z] ){  /* Switch on the character-class of the first byte
                          ** of the token. See the comment on the CC_ defines
                          ** above. */
    case 7    : {
      ;
      ;
      ;
      ;
      ;
      for(i=1; (sqlite3CtypeMap[(unsigned char)(z[i])]&0x01); i++){}
      *tokenType = 184;
      return i;
    }
    case 11    : {
      if( z[1]=='-' ){
        for(i=2; (c=z[i])!=0 && c!='\n'; i++){}
        *tokenType = 185;
        return i;
      }else if( z[1]=='>' ){
        *tokenType = 113;
        return 2 + (z[2]=='>');
      }
      *tokenType = 108;
      return 1;
    }
    case 17    : {
      *tokenType = 22;
      return 1;
    }
    case 18    : {
      *tokenType = 23;
      return 1;
    }
    case 19    : {
      *tokenType = 1;
      return 1;
    }
    case 20    : {
      *tokenType = 107;
      return 1;
    }
    case 21    : {
      *tokenType = 109;
      return 1;
    }
    case 16    : {
      if( z[1]!='*' || z[2]==0 ){
        *tokenType = 110;
        return 1;
      }
      for(i=3, c=z[2]; (c!='*' || z[i]!='/') && (c=z[i])!=0; i++){}
      if( c ) i++;
      *tokenType = 185;
      return i;
    }
    case 22    : {
      *tokenType = 111;
      return 1;
    }
    case 14    : {
      *tokenType = 54;
      return 1 + (z[1]=='=');
    }
    case 12    : {
      if( (c=z[1])=='=' ){
        *tokenType = 56;
        return 2;
      }else if( c=='>' ){
        *tokenType = 53;
        return 2;
      }else if( c=='<' ){
        *tokenType = 105;
        return 2;
      }else{
        *tokenType = 57;
        return 1;
      }
    }
    case 13    : {
      if( (c=z[1])=='=' ){
        *tokenType = 58;
        return 2;
      }else if( c=='>' ){
        *tokenType = 106;
        return 2;
      }else{
        *tokenType = 55;
        return 1;
      }
    }
    case 15    : {
      if( z[1]!='=' ){
        *tokenType = 186;
        return 1;
      }else{
        *tokenType = 53;
        return 2;
      }
    }
    case 10    : {
      if( z[1]!='|' ){
        *tokenType = 104;
        return 1;
      }else{
        *tokenType = 112;
        return 2;
      }
    }
    case 23    : {
      *tokenType = 25;
      return 1;
    }
    case 24    : {
      *tokenType = 103;
      return 1;
    }
    case 25    : {
      *tokenType = 115;
      return 1;
    }
    case 8    : {
      int delim = z[0];
      ;
      ;
      ;
      for(i=1; (c=z[i])!=0; i++){
        if( c==delim ){
          if( z[i+1]==delim ){
            i++;
          }else{
            break;
          }
        }
      }
      if( c=='\'' ){
        *tokenType = 118;
        return i+1;
      }else if( c!=0 ){
        *tokenType = 60;
        return i+1;
      }else{
        *tokenType = 186;
        return i;
      }
    }
    case 26    : {

      if( !(sqlite3CtypeMap[(unsigned char)(z[1])]&0x04) )

      {
        *tokenType = 142;
        return 1;
      }
      /* If the next character is a digit, this is a floating point
      ** number that begins with ".".  Fall thru into the next case */
      /* no break */ 
    }
    case 3    : {
      ;  ;  ;
      ;  ;  ;
      ;  ;  ;
      ;  ;
      *tokenType = 156;

      if( z[0]=='0' && (z[1]=='x' || z[1]=='X') && (sqlite3CtypeMap[(unsigned char)(z[2])]&0x08) ){
        for(i=3; 1; i++){
          if( (sqlite3CtypeMap[(unsigned char)(z[i])]&0x08)==0 ){
            if( z[i]=='_' ){
              *tokenType = 183;
            }else{
              break;
            }
          }
        }
      }else

        {
        for(i=0; 1; i++){
          if( (sqlite3CtypeMap[(unsigned char)(z[i])]&0x04)==0 ){
            if( z[i]=='_' ){
              *tokenType = 183;
            }else{
              break;
            }
          }
        }

        if( z[i]=='.' ){
          if( *tokenType==156 ) *tokenType = 154;
          for(i++; 1; i++){
            if( (sqlite3CtypeMap[(unsigned char)(z[i])]&0x04)==0 ){
              if( z[i]=='_' ){
                *tokenType = 183;
              }else{
                break;
              }
            }
          }
        }
        if( (z[i]=='e' || z[i]=='E') &&
             ( (sqlite3CtypeMap[(unsigned char)(z[i+1])]&0x04)
              || ((z[i+1]=='+' || z[i+1]=='-') && (sqlite3CtypeMap[(unsigned char)(z[i+2])]&0x04))
             )
        ){
          if( *tokenType==156 ) *tokenType = 154;
          for(i+=2; 1; i++){
            if( (sqlite3CtypeMap[(unsigned char)(z[i])]&0x04)==0 ){
              if( z[i]=='_' ){
                *tokenType = 183;
              }else{
                break;
              }
            }
          }
        }

      }
      while( ((sqlite3CtypeMap[(unsigned char)z[i]]&0x46)!=0) ){
        *tokenType = 186;
        i++;
      }
      return i;
    }
    case 9    : {
      for(i=1, c=z[0]; c!=']' && (c=z[i])!=0; i++){}
      *tokenType = c==']' ? 60 : 186;
      return i;
    }
    case 6    : {
      *tokenType = 157;
      for(i=1; (sqlite3CtypeMap[(unsigned char)(z[i])]&0x04); i++){}
      return i;
    }
    case 4    :
    case 5    : {
      i64 n = 0;
      ;  ;
      ;  ;
      *tokenType = 157;
      for(i=1; (c=z[i])!=0; i++){
        if( ((sqlite3CtypeMap[(unsigned char)c]&0x46)!=0) ){
          n++;

        }else if( c=='(' && n>0 ){
          do{
            i++;
          }while( (c=z[i])!=0 && !(sqlite3CtypeMap[(unsigned char)(c)]&0x01) && c!=')' );
          if( c==')' ){
            i++;
          }else{
            *tokenType = 186;
          }
          break;
        }else if( c==':' && z[i+1]==':' ){
          i++;

        }else{
          break;
        }
      }
      if( n==0 ) *tokenType = 186;
      return i;
    }
    case 1    : {
      if( aiClass[z[1]]>2     ){ i = 1;  break; }
      for(i=2; aiClass[z[i]]<=2    ; i++){}
      if( ((sqlite3CtypeMap[(unsigned char)z[i]]&0x46)!=0) ){
        /* This token started out using characters that can appear in keywords,
        ** but z[i] is a character not allowed within keywords, so this must
        ** be an identifier instead */
        i++;
        break;
      }
      *tokenType = 60;
      return keywordCode((char*)z, i, tokenType);
    }
    case 0    : {

      ; ;
      if( z[1]=='\'' ){
        *tokenType = 155;
        for(i=2; (sqlite3CtypeMap[(unsigned char)(z[i])]&0x08); i++){}
        if( z[i]!='\'' || i%2 ){
          *tokenType = 186;
          while( z[i] && z[i]!='\'' ){ i++; }
        }
        if( z[i] ) i++;
        return i;
      }

      /* If it is not a BLOB literal, then it must be an ID, since no
      ** SQL keywords start with the letter 'x'.  Fall through */
      /* no break */ 
    }
    case 2    :
    case 27    : {
      i = 1;
      break;
    }
    case 30    : {
      if( z[1]==0xbb && z[2]==0xbf ){
        *tokenType = 184;
        return 3;
      }
      i = 1;
      break;
    }
    case 29    : {
      *tokenType = 186;
      return 0;
    }
    default: {
      *tokenType = 186;
      return 1;
    }
  }
  while( ((sqlite3CtypeMap[(unsigned char)z[i]]&0x46)!=0) ){ i++; }
  *tokenType = 60;
  return i;
}

/*
** Run the parser on the given SQL string.
*/
static int sqlite3RunParser(Parse *pParse, const char *zSql){
  int nErr = 0;                   /* Number of errors encountered */
  void *pEngine;                  /* The LEMON-generated LALR(1) parser */
  i64 n = 0;                      /* Length of the next token token */
  int tokenType;                  /* type of the next token */
  int lastTokenParsed = -1;       /* type of the previous token */
  sqlite3 *db = pParse->db;       /* The database connection */
  i64 mxSqlLen;                   /* Max length of an SQL string */
  Parse *pParentParse = 0;        /* Outer parse context, if any */

  yyParser sEngine;    /* Space to hold the Lemon-generated Parser object */

  ;

  ;
  mxSqlLen = db->aLimit[1];
  if( db->nVdbeActive==0 ){
    (*(&db->u1.isInterrupted) = (0));
  }
  pParse->rc = 0   ;
  pParse->zTail = zSql;









  pEngine = &sEngine;
  sqlite3ParserInit(pEngine, pParse);







  ;
  ;
  ;
  ;
  pParentParse = db->pParse;
  db->pParse = pParse;
  while( 1 ){
    n = sqlite3GetToken((u8*)zSql, &tokenType);
    mxSqlLen -= n;
    if( mxSqlLen<0 ){
      pParse->rc = 18   ;
      pParse->nErr++;
      break;
    }

    if( tokenType>=165 ){
      ;






      if( (*(&db->u1.isInterrupted)) ){
        pParse->rc = 9   ;
        pParse->nErr++;
        break;
      }
      if( tokenType==184 ){
        zSql += n;
        continue;
      }
      if( zSql[0]==0 ){
        /* Upon reaching the end of input, call the parser two more times
        ** with tokens TK_SEMI and 0, in that order. */
        if( lastTokenParsed==1 ){
          tokenType = 0;
        }else if( lastTokenParsed==0 ){
          break;
        }else{
          tokenType = 1;
        }
        n = 0;

      }else if( tokenType==165 ){
        ;
        tokenType = analyzeWindowKeyword((const u8*)&zSql[6]);
      }else if( tokenType==166 ){
        ;
        tokenType = analyzeOverKeyword((const u8*)&zSql[4], lastTokenParsed);
      }else if( tokenType==167 ){
        ;
        tokenType = analyzeFilterKeyword((const u8*)&zSql[6], lastTokenParsed);

      }else if( tokenType==185
             && (db->init.busy || (db->flags & ((u64)(0x00040)<<32) )!=0)
      ){
        /* Ignore SQL comments if either (1) we are reparsing the schema or
        ** (2) SQLITE_DBCONFIG_ENABLE_COMMENTS is turned on (the default). */
        zSql += n;
        continue;
      }else if( tokenType!=183 ){
        Token x;
        x.z = zSql;
        x.n = (u32)n;
        sqlite3ErrorMsg(pParse, "unrecognized token: \"%T\"", &x);
        break;
      }
    }
    pParse->sLastToken.z = zSql;
    pParse->sLastToken.n = (u32)n;
    sqlite3Parser(pEngine, tokenType, pParse->sLastToken);
    lastTokenParsed = tokenType;
    zSql += n;
    ;
    if( pParse->rc!=0    ) break;
  }
  ;








  sqlite3ParserFinalize(pEngine);



  if( db->mallocFailed ){
    pParse->rc = 7   ;
  }
  if( pParse->zErrMsg || (pParse->rc!=0    && pParse->rc!=101  ) ){
    if( pParse->zErrMsg==0 ){
      pParse->zErrMsg = sqlite3DbStrDup(db, sqlite3ErrStr(pParse->rc));
    }
    if( (pParse->prepFlags & 0x10)==0 ){
      sqlite3_log(pParse->rc, "%s in \"%s\"", pParse->zErrMsg, pParse->zTail);
    }
    nErr++;
  }
  pParse->zTail = zSql;

  sqlite3_free(pParse->apVtabLock);


  if( pParse->pNewTable && !(pParse->eParseMode!=0) ){
    /* If the pParse->declareVtab flag is set, do not delete any table
    ** structure built up in pParse->pNewTable. The calling code (see vtab.c)
    ** will take responsibility for freeing the Table structure.
    */
    sqlite3DeleteTable(db, pParse->pNewTable);
  }
  if( pParse->pNewTrigger && !(pParse->eParseMode>=2) ){
    sqlite3DeleteTrigger(db, pParse->pNewTrigger);
  }
  if( pParse->pVList ) sqlite3DbNNFreeNN(db, pParse->pVList);
  db->pParse = pParentParse;
  ;
  return nErr;
}


































































































































